import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
void main()=>runApp(const ApiLabApp());
class ApiLabApp extends StatelessWidget { const ApiLabApp({super.key}); @override Widget build(BuildContext context)=>MaterialApp(debugShowCheckedModeBanner:false, theme:ThemeData(colorSchemeSeed:Colors.teal,useMaterial3:true), home:const ApiPage()); }
class ApiPage extends StatefulWidget { const ApiPage({super.key}); @override State<ApiPage> createState()=>_ApiPageState(); }
class _ApiPageState extends State<ApiPage> {
  static const endpoint='https://fakestoreapi.com/products';
  late Future<List<dynamic>> _future; final _search=TextEditingController(); String _query='';
  @override void initState(){super.initState();_future=_fetch();}
  Future<List<dynamic>> _fetch() async { final response=await http.get(Uri.parse(endpoint)); if(response.statusCode<200||response.statusCode>=300){throw Exception('HTTP ${response.statusCode}');} final data=jsonDecode(response.body); if(data is List)return data; return [data]; }
  void _retry(){setState(()=>_future=_fetch());}
  @override void dispose(){_search.dispose();super.dispose();}
  @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('LabSheet-9 Q15'),actions:[IconButton(onPressed:_retry,icon:const Icon(Icons.refresh))]), body:Column(children:[Padding(padding:const EdgeInsets.all(12),child:Text('Develop a Flutter Product Store Application that fetches a list of products (title, price, and image) from a public REST API, displays them in a GridView, and shows product details on a separate screen with a loading indicator and error handling.')), if(true) Padding(padding:const EdgeInsets.symmetric(horizontal:12),child:TextField(controller:_search,onChanged:(v)=>setState(()=>_query=v),decoration:const InputDecoration(labelText:'Search results',prefixIcon:Icon(Icons.search),border:OutlineInputBorder()))), Expanded(child:RefreshIndicator(onRefresh:()async=>_retry(),child:FutureBuilder<List<dynamic>>(future:_future,builder:(context,snapshot){if(snapshot.connectionState==ConnectionState.waiting)return const Center(child:CircularProgressIndicator());if(snapshot.hasError)return Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Text('Unable to load data: ${snapshot.error}'),const SizedBox(height:8),FilledButton(onPressed:_retry,child:const Text('Retry'))]));final items=snapshot.data??[];final filtered=items.where((e)=>e.toString().toLowerCase().contains(_query.toLowerCase())).toList();if(filtered.isEmpty)return const Center(child:Text('No data found'));return ListView.builder(itemCount:filtered.length,itemBuilder:(context,i){final item=filtered[i]; final title=item is Map?(item['title']??item['name']??item['product']??'Item ${i+1}').toString():'Item ${i+1}';final body=item is Map?(item['body']??item['email']??item['description']??item.toString()).toString():item.toString();return Card(margin:const EdgeInsets.symmetric(horizontal:12,vertical:5),child:ListTile(leading:CircleAvatar(child:Text('${i+1}')),title:Text(title,maxLines:2,overflow:TextOverflow.ellipsis),subtitle:Text(body,maxLines:3,overflow:TextOverflow.ellipsis),onTap:()=>showDialog(context:context,builder:(ctx)=>AlertDialog(title:Text(title),content:SingleChildScrollView(child:Text(const JsonEncoder.withIndent('  ').convert(item))),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Close'))]))));});}))))]));
}
